code.code:
func parsePort(n int) (int, error) {
    if n < 1 || n > 65535 {
        return 0, errors.New("порт вне диапазона")
    }
    return n, nil
}

func main() {
    for _, n := range []int{8080, 70000} {
        port, err := parsePort(n)
        if err != nil {
            fmt.Println("ошибка:", err)
            continue
        }
        fmt.Println("порт", port)
    }
}

